-- ============================================================
-- API Learning Lab schema + seed data
-- Domains: remote sensing, ocean observation, weather, ship trajectory
-- ============================================================

CREATE TABLE IF NOT EXISTS dataset (
    id             BIGSERIAL PRIMARY KEY,
    title          VARCHAR(255) NOT NULL,
    description    TEXT,
    resource_type  VARCHAR(50)  NOT NULL,
    publish_year   INTEGER,
    status         VARCHAR(20)  NOT NULL DEFAULT 'draft',
    price          NUMERIC(10, 2) DEFAULT 0,
    is_public      BOOLEAN DEFAULT TRUE,
    tags           JSONB DEFAULT '[]',
    metadata       JSONB DEFAULT '{}',
    location       JSONB DEFAULT '{}',
    created_time   TIMESTAMP DEFAULT now(),
    updated_time   TIMESTAMP DEFAULT now(),
    file_size      BIGINT DEFAULT 0
);

CREATE TABLE IF NOT EXISTS dataset_file (
    id             BIGSERIAL PRIMARY KEY,
    dataset_id     BIGINT NOT NULL REFERENCES dataset(id) ON DELETE CASCADE,
    file_name      VARCHAR(255) NOT NULL,
    file_path      VARCHAR(500) NOT NULL,
    file_type      VARCHAR(50),
    file_size      BIGINT,
    created_time   TIMESTAMP DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_dataset_resource_type ON dataset(resource_type);
CREATE INDEX IF NOT EXISTS idx_dataset_status        ON dataset(status);
CREATE INDEX IF NOT EXISTS idx_dataset_publish_year  ON dataset(publish_year);
CREATE INDEX IF NOT EXISTS idx_dataset_file_dataset_id ON dataset_file(dataset_id);

